async function pageFunction(context) {
    const { page, request, log } = context;

    // Handle search results / listing pages - just let them enqueue job links via linkSelector
    if (request.url.includes('/search-results-usa')) {
        log.info(`Listing page: ${request.url}`);
        await new Promise(r => setTimeout(r, 3000));

        // Count jobs on this page for logging
        const jobCount = await page.evaluate(() => {
            const jobLinks = document.querySelectorAll('a[href*="/job/"]');
            return jobLinks.length;
        });
        log.info(`Found ${jobCount} job links on this page - will be enqueued by linkSelector`);

        return null; // Don't return data for listing pages
    }

    // Handle individual job pages
    if (request.url.includes('/job/')) {
        log.info(`Extracting job: ${request.url}`);
        await new Promise(r => setTimeout(r, 2000));

        const jobData = await page.evaluate(() => {
            const result = {};

            // Helper to decode HTML entities
            const decodeHtml = (html) => {
                const txt = document.createElement('textarea');
                txt.innerHTML = html;
                return txt.value;
            };

            // Extract from JSON-LD structured data
            const jsonLdScript = document.querySelector('script[type="application/ld+json"]');
            if (jsonLdScript) {
                try {
                    const jsonLd = JSON.parse(jsonLdScript.textContent);
                    if (jsonLd['@type'] === 'JobPosting') {
                        result.jobTitle = jsonLd.title || null;

                        // Clean description
                        let desc = jsonLd.description || '';

                        // Decode HTML entities
                        desc = decodeHtml(desc);

                        // ===== REMOVE END BOILERPLATE FIRST =====

                        // EEO boilerplate
                        const eeoIndex = desc.indexOf('EEO Employer');
                        if (eeoIndex > 0) {
                            desc = desc.substring(0, eeoIndex);
                        }
                        const eeoIndex2 = desc.indexOf('Apex Systems is an equal opportunity employer');
                        if (eeoIndex2 > 0) {
                            desc = desc.substring(0, eeoIndex2);
                        }

                        // Benefits boilerplate at end
                        desc = desc.replace(/\*?Please note that as a contract employee of Apex Systems[\s\S]*$/i, '');
                        desc = desc.replace(/Apex Benefits Overview[\s\S]*$/i, '');

                        // Military & Veteran Programs boilerplate at end
                        desc = desc.replace(/\s*Apex Systems Military & Veteran Programs[\s\S]*$/i, '');

                        // ADA/Accommodation notice at end
                        desc = desc.replace(/\s*If you have visited our website in search of information[\s\S]*$/i, '');

                        // ===== REMOVE START BOILERPLATE =====

                        // Pattern: "Job #: XXXXX Apex Systems is currently hiring for X with..." (combined)
                        desc = desc.replace(/^Job\s*#?:?\s*\d+\s*Apex Systems is currently hiring for [^.]+\.\s*/i, '');

                        // Remove "Job #: XXXXX " prefix at very start (standalone)
                        desc = desc.replace(/^Job\s*#?:?\s*\d+\s*/i, '');

                        // Pattern: "Apex Systems is currently hiring for X with..." through @apexsystems.com
                        desc = desc.replace(/^Apex Systems is currently hiring for [^@]+@apexsystems\.com\.?\s*/i, '');

                        // Pattern: "Apex Systems is currently hiring for a X with..." (without email - ends at period)
                        desc = desc.replace(/^Apex Systems is currently hiring for (?:a |an )?[^.]+(?:solutions|services|leader|company|clients)[^.]*\.\s*/i, '');

                        // Pattern: "Apex Systems has an opening available for..." through @apexsystems.com
                        desc = desc.replace(/^Apex Systems has an opening available for [^@]+@apexsystems\.com\.?\s*/i, '');

                        // Pattern: "Apex Systems has an opening available for..." without email (ends after "apply TODAY!")
                        desc = desc.replace(/^Apex Systems has an opening available for [^!]+!\s*/i, '');

                        // Pattern: "Apex Systems, a World-Class..." through @apexsystems.com
                        desc = desc.replace(/^Apex Systems,? a World-Class Technology Solutions Provider[^@]+@apexsystems\.com\.?\s*/i, '');

                        // Pattern: "Apex Systems is a world class...Here are the details:"
                        desc = desc.replace(/^Apex Systems is a world class[\s\S]*?Here are the details:\s*/i, '');

                        // Pattern: "Apex Systems has an opportunity for..."
                        desc = desc.replace(/^Apex (?:Systems )?has an opportunity for[^.]+\.\s*/i, '');

                        // ===== REMOVE INLINE BOILERPLATE (anywhere in text) =====

                        // Pattern: "Apex Systems is hiring for multiple X with...!" (anywhere)
                        desc = desc.replace(/Apex Systems is hiring for (?:multiple )?[^!]+!\s*/gi, '');

                        // Pattern: "If interested in applying...@apexsystems.com" (anywhere, with or without parenthetical)
                        desc = desc.replace(/If interested in applying[^@]+@apexsystems\.com\s*(?:\([^)]+\))?\s*/gi, '');

                        // Pattern: "If you are interested...@apexsystems.com" (anywhere)
                        desc = desc.replace(/If you are interested(?:,| in learning more)?,? (?:please )?(?:apply|send)[^@]*@apexsystems\.com\.?\s*/gi, '');

                        // Pattern: "**Please note that only qualified candidates will be contacted"
                        desc = desc.replace(/\*{0,2}Please note that only qualified candidates will be contacted\s*/gi, '');

                        // Pattern: "apply TODAY and/or" or "apply TODAY!"
                        desc = desc.replace(/apply TODAY!?\s*(?:and\/or)?\s*/gi, '');

                        // Remove recruiter contact intro sentences (fallback patterns)
                        desc = desc.replace(/^To apply,? email [^\n]{0,60}@apexsystems\.com[^\n]*\n?/i, '');
                        desc = desc.replace(/^For applicants[^\n]{0,100}@apexsystems\.com[^\n]*\n?/i, '');

                        // Clean up excessive whitespace
                        desc = desc.replace(/\n{3,}/g, '\n\n');

                        result.description = desc.trim();

                        result.employmentType = jsonLd.employmentType || null;
                        result.datePosted = jsonLd.datePosted || null;
                        if (jsonLd.identifier && jsonLd.identifier.value) {
                            result.jobNumber = String(jsonLd.identifier.value);
                        }
                        if (jsonLd.jobLocation && jsonLd.jobLocation.address) {
                            const addr = jsonLd.jobLocation.address;
                            result.location = [addr.addressLocality, addr.addressRegion].filter(Boolean).join(', ');
                        }
                    }
                } catch (e) { }
            }

            // Get additional fields from body text
            const bodyText = document.body.innerText;

            const extractField = (patterns) => {
                for (const pattern of patterns) {
                    const match = bodyText.match(pattern);
                    if (match) return match[1].trim().split('\n')[0];
                }
                return null;
            };

            // Security clearance - multiple patterns
            result.securityClearance = extractField([
                /Security Clearance:\s*([^\n]{5,80})/i,
                /Clearance requirement:\s*([^\n]{5,80})/i,
                /Clearance[^:]*:\s*((?:Active\s+)?(?:TS\/SCI|Top Secret|Secret|Public Trust)[^\n]{0,60})/i,
                /((?:Top Secret|TS\/SCI|Secret)\s+clearance[^\n]{0,40}(?:required|preferred|acceptable)[^\n]{0,30})/i,
                /((?:Active|Current)\s+(?:Top Secret|TS\/SCI|Secret)[^\n]{0,40})/i
            ]);

            // Pay rate - look for various patterns
            result.payRate = extractField([
                /Pay Rate:\s*([^\n]+)/i, 
                /Rate:\s*(\$[^\n]+|Negotiable[^\n]*)/i,
                /Pay:\s*(\$[^\n]+)/i,
                /Base Salary[:\s]*(\$?[\d,]+-?[\d,]*(?:k|K)?)/i,
                /Salary[:\s]*(\$?[\d,]+-?[\d,]*(?:k|K)?)/i
            ]);

            // Duration
            result.duration = extractField([
                /Project Duration:\s*([^\n]+)/i, 
                /Duration:\s*([^\n]+)/i, 
                /Contract Length:\s*([^\n]+)/i
            ]);

            return result;
        });

        return { url: request.url, ...jobData, scrapedAt: new Date().toISOString() };
    }

    // Unknown page type
    log.warning(`Unknown page type: ${request.url}`);
    return null;
}
